import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"天水讼","description":"周易折中 - 天水讼","frontmatter":{"title":"天水讼","description":"周易折中 - 天水讼"},"headers":[],"relativePath":"zh/classics/zhezhong/012.md","filePath":"zh/classics/zhezhong/012.md"}'),h={name:"zh/classics/zhezhong/012.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="天水讼" tabindex="-1">天水讼 <a class="header-anchor" href="#天水讼" aria-label="Permalink to “天水讼”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>序卦曰：饮食必有讼，故受之以讼。人之所需者饮食，既有所湏争讼所由起也。讼所以次需也。为卦干上坎下，以二象言之，天阳上行，水性就下，其行相违所以成讼也。以二体言之上刚下险，刚险相接能无讼乎？又人内险阻而外刚强，所以讼也。</p><p>讼：有孚窒惕，中吉，终凶。利见大人，不利涉大川。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>讼，即争辨。卦象上干下坎，干代表刚健，坎代表险阻。上卦之刚用以制约下卦之险，下卦之险则伺机上攻上卦，形成内险外健、己险彼健的局面，这都是讼卦所揭示的争讼之道。九二爻居中而实，上无相应之爻，象征有诚信却被窒塞，能因此产生惕惧之心而求得中道，故为中吉之象。上九爻过刚，居讼卦之极，象征讼事终极无休，故为终凶之象。九五爻刚健中正，居尊位，有大人之象；同时，九五爻以刚乘险，以实履陷，故又有不利涉大川之象。因此，占此卦者，必有争辨之事，而吉凶则随其所处之位而定。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>讼卦之道，必以诚信为本。中实有信，则无虚妄，此吉道也。卦中九二爻实而有信，乃为有孚之象。然而，讼者与人争辨，须待他人决断，虽有诚信，亦可能遭遇窒塞未通之境。若不知窒塞而妄行，则易生讼事。事既未明，吉凶亦未可知，故当心怀惕惧。能中道而止，则得吉；若终极其讼，则必凶。讼者所求，在于辨明曲直，故利于见大人。大人刚明中正，能决所讼。讼非和平之事，当择安地而处，不可涉险，故不利涉大川。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：窒，塞也；惕，惧也。凡讼之体，不可妄兴，必有信实。被物止塞而能惕惧，中道而止，乃得吉。终凶者，讼不可长，若终竟讼事，虽复窒惕，亦有凶。物既有讼，须大人决之，故利见大人。若以讼而往涉危难，必有祸患，故不利涉大川。</p></li><li><p>胡氏瑗曰 ：孚者，由中之信。人所以兴讼，必有由中之信而为他人之所窒塞，不得已而兴讼。然虽已有信实，而为人之窒塞，亦须恐惧竞慎而不敢自安，则庶几可免于凶祸。又中道而止，则可以获吉。大川，谓大险大难也。凡历险涉难，必须物情相协，志气和同，则可得而济也。今讼之时，物情违忤而不相得，欲济涉险难，必不可得。</p></li><li><p>朱子语类云 ：大凡卦辞取义不一。如讼有孚窒惕中吉，盖取九二中实、坎为加忧之象；终凶，盖取上九终极于讼之象；利见大人，盖取九五刚健中正居尊之象；不利涉大川，又取以刚乘险、以实履陷之象。此取义不一也。然亦有不必如此取者，此特其一例也。卦辞如此，辞极齐整，盖所取诸爻义皆与爻中本辞协。亦有虽取爻义而与爻本辞不同者。</p></li><li><p>项氏安世曰 ：利见大人，或不与之校，如直不疑；或为之和解，如卓茂；或使其心化，如王烈；或为之辨明，如仲由，皆讼者之利也。不利涉大川，涉险之道利在同心，此岂相争之时哉？</p></li></ul><p>象曰：天与水违行，讼。君子以作事谋始</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>天上水下，其行相违，作事谋始，讼端绝矣。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>天上水下，相违而行，二体违戾，讼之由也。若上下相顺，讼何由兴？君子观象，知人情有争讼之道，故凡所作事必谋其始。绝讼端于事之始，则讼无由生矣。谋始之义广矣，若慎交结、明契劵之类是也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>吴氏澄曰：水行而下，天行而上，其行两相背戾，是违行也。</p></li><li><p>胡氏炳文曰：凡事有始有中有终，讼中吉终凶。然能谋于其始，则讼端既绝，中与终不必言矣。</p></li><li><p>林氏希元曰：讼不兴于讼之日，而兴于作事之始。作事不豫谋，此讼端之所由起也。故君子于其始而谋之，看事理有无违碍，人情有无违拂，终久有无祸患。凡其事之不善而可以致讼者，皆杜绝之而不为，则讼端无自起矣。</p></li></ul><p>彖曰：讼，上刚下险，险而健，讼。</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦徳释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>讼之为卦，上刚下险，险而又健也。又为险健相接，内险外健，皆所以为讼也。若健而不险，不生讼也；险而不健，不能讼也；险而又健，是以讼也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>毛氏璞曰：上刚下险，以彼此言之；险而健，以一人言之。</li></ul><p>讼有孚，窒惕中吉，刚来而得中也。终凶，讼不可成也。利见大人，尚中正也。不利涉大川，入于渊也。</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦变、卦体、卦象释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>讼之道固如是，又据卦才而言。九二以刚自外来而成讼，则二乃讼之主也。以刚处中，中实之象，故为有孚。处讼之时，虽有孚信，亦必艰阻窒塞而有惕惧。不窒则不成讼矣，又居险陷之中，亦为窒塞惕惧之义。二以阳刚自外来而得中为以刚来讼而不过之义，是以吉也。卦有更取成卦之由为义者，此是也。卦义不取成卦之由，则更不言所变之爻也。据卦辞，二乃善也，而爻中不见其善，盖卦辞取其有孚得中而言乃善也，爻则以自下讼上为义，所取不同也。讼非善事，不得已也，安可终极其事？极意于其事则凶矣，故曰不可成也。成谓穷尽其事也。讼者求辩其是非也，辩之当乃中正也，故利见大人。以所尚者中正也，听者非其人，则或不得其中正也。中正大人，九五是也。与人讼者，必处其身于安平之地，若蹈危险，则陷其身矣，乃入于深渊也。卦中有中正、险陷之象。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：刚来而得中，辅嗣必以为九二者，凡上下二象在于下象者，则称来，故贲卦云“柔来而文刚”，是离下艮上而称柔来。今此云“刚来而得中”，故知九二也。且凡云来者，皆据异类而来，九二在二阴之中，故称来。若于爻辞之中，亦有从下卦向上卦称来者，故需上六有“不速之客三人来”，谓下卦三阳，然需上六阴爻，阳来诣之，亦是非类而称来也。</p></li><li><p>刘氏牧曰：刚来谓二也，性本刚好胜而讼也。来居柔，能屈其性也。处中位，不失中道也。</p></li><li><p>王氏安石曰：彖言乎其才也。讼有孚窒惕中吉，此言九二之才也；终凶，此言上九之才也；利见大人，言九五之才也；不利涉大川，言一卦之才也。</p></li><li><p>蔡氏清曰：讼不可成，以理言之，扬人之恶也，烦上之听也，损己之徳也，増俗之偷也。又人己之间俱废其业，虽得不偿失也，此岂君子之所乐成者哉？谓之不可成，见其宜惕中也。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>彖传中有言刚柔往来上下者，皆虚象也。先儒因此而卦变之说纷然，然观泰、否卦“下小往大来，大往小来”云者，文王之辞也，果从何卦而往何卦而来乎？亦云有其象而已耳。故依王、孔注疏作虚象者近是。</p><p>初六：不永所事，小有言，终吉</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>阴柔居下，不能终讼，故其象占如此。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>六以柔弱居下，不能终极其讼者也。故于讼之初，因六之才为之戒曰：若不长永其事，则虽小有言，终得吉也。盖讼非可长之事，以阴柔之才而讼于下，难以吉矣。以上有应援，而能不永其事故，虽小有言，终得吉也。有言，灾之小者也。不永其事，而不至于凶，乃讼之吉也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：处讼之初，讼不可终，故不永所事，然后乃吉。凡阳唱而阴和，阴非先唱者也。处讼之初，不为讼先，虽不能不讼，而必辨明也。</p></li><li><p>杨氏简曰 ：讼之初不深，有不永所事之象。讼之初未深，小有言而已。既不永其事，故终吉。</p></li><li><p>胡氏炳文曰 ：初不曰不永讼，而曰不永所事。事之初，犹冀其不成讼也。小有言与需不同，需小有言，人不能不小有言也。此之小有言，我不能已而小有言也。</p></li></ul><p>象曰：不永所事，讼不可长也。虽小有言，其辩明也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>六以柔弱而讼于下，其义固不可长永也。永其讼则不胜而祸难及矣。又于讼之初即戒讼，非可长之事也。柔弱居下，才不能讼，虽不永所事，既讼矣，必有小灾，故“小有言”也。既不永其事，又上有刚阳之正应，辩理之明，故终得其吉也。不然，其能免乎？在讼之义，同位而相应相与者也，故初于四为获其辩明；同位而不相得，相讼者也，故二与五为对敌也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏申子曰：止讼于初者上也，故于讼之初即以讼不可长为戒。</p></li><li><p>俞氏琰曰：彖传云“讼不可成”，盖言讼之通义而不欲其成；爻传云“讼不可长”，盖言初为讼端而不欲其长。</p></li></ul><p>九二：不克讼，归而逋，其邑人三百户，无眚</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>九二阳刚为险之主，本欲讼者也。然以刚居柔，得下之中而上应九五阳刚居尊，势不可敌，故其象占如此。邑人三百户，邑之小者，言自处卑约以免灾患。占者如是，则无眚矣。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二五相应之地，而两刚不相与相讼者也。九二自外来，以刚处险为讼之主，乃与五为敌。五以中正处君位，其可敌乎？是为讼而义不克也。若能知其义之不可，退归而逋避，以寡约自处，则得无过眚也。必逋者，避为敌之地也。三百户，邑之至小者。若处强大，是犹竞也，能无眚乎？眚，过也。处不当也，与知恶而为有分也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>荀氏爽曰 ：二者下体之君，君不争则百姓无害也。</p></li><li><p>王氏弼曰 ：以刚处讼，不能下物。自下讼上，宜其不克。若能以惧归窜其邑，乃可以免灾。邑过三百，窜而据强，灾未免也。</p></li><li><p>项氏安世曰 ：一家好讼，则百家受害。言三百户无眚，见安者之众也。</p></li><li><p>俞氏琰曰 ：九二以刚居柔，故不克讼逋逃也。既逋，则近已者皆无连坐之患，故曰其邑人三百户无眚。</p></li></ul><p>象曰：不克讼，归逋窜也；自下讼上，患至掇也</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>掇，自取也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>义既不敌，故不能讼，归而逋窜，避去其所也。自下而讼其上，义乖势屈，祸患之至，犹拾掇而取之，言易得也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰：上两句皆是爻辞，下两句方是象传，如需之上六象传句法。</p></li><li><p>王氏申子曰：知义不克，归而逋窜，犹可免祸。若不知自反，则祸患之至，如掇拾而取之矣。彖称“二刚来而得中”，而爻义乃如此。盖彖总言一卦之体，爻则据其时之用以言之也。</p></li></ul><p>六三：食旧德，贞厉，终吉，或从王事，无成</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>食犹食邑之食，言所享也。六三阴柔，非能讼者，故守旧居正则虽危而终吉。然或出而从上之事，则亦必无成功。占者守常而不出，则善也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>三虽居刚而应上，然质本阴柔，处险而介二刚之闲，危惧非为讼者也。禄者称德而受，食旧德谓处其素分。贞谓坚固自守，厉终吉谓虽处危地，能知危惧，则终必获吉也。守素分而无求，则不讼矣。处危谓在险而承乘皆刚，与居讼之时也。柔从刚者也，下从上者也。三不为讼而从上九所为，故曰或从王事无成。谓从上而成不在已也。讼者刚健之事故，初则不永，三则从上，皆非能讼者也。二爻皆以阴柔不终而得吉，四亦以不克而渝得吉，讼以能止为善也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰 ：道无成而代有终，故曰无成。坤三同义也。</p></li><li><p>胡氏瑗曰 ：无成者，不敢居其成，但从王事，守其本位本禄而已，故获其吉也。</p></li><li><p>徐氏几曰 ：圣人于初三两柔爻，皆系之以终吉之辞，所以勉人之无讼也。苟知柔而不喜讼者终吉，则知刚而好讼者终凶矣。</p></li><li><p>李氏简曰 ：或从王事无成者，谓从王事而不以成功自居也。夫讼生于其行之相违，而天下之讼又起于矜功而伐善。以柔而从刚，以下而从上，有功而不自居，故能不失旧德，而终又获吉也。</p></li><li><p>胡氏炳文曰 ：食旧德与位乎天德语同，位必称德而居，故宁德过其位，毋位过其德。食必称德而食，故宁德浮于食，毋食浮于德。食犹食邑之食，九二邑人三百户，富之最约者也。二刚险本欲讼者，能退处于分之小仅，可无眚。三阴柔本不能讼者，能守其分之常，虽厉犹吉。</p></li><li><p>杨氏启新曰 ：食旧德，安其分之所当得，是不与人竞利也。或从王事者，分之所不得越，是不与人竞功也。盖不必告讦之风乃谓之讼，一有争竞之心亦讼也。</p></li></ul><h3 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to “附录”">​</a></h3><ul><li>徐氏几曰 ：王事即讼事，无成即彖之讼不可成也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>本义是戒人以不可从王事也。但此爻与坤三之文大同小异，不应其义差殊。故诸家之说，可以与本义相参。而杨氏尤为明畅也。徐氏即以讼不可成为解，亦可备一说。</p><p>象曰：食旧徳，从上吉也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>从上吉，谓随人则吉，明自主事则无成功也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>守其素分，虽从上之所为，非由己也，故无成而终得其吉也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>乔氏中和曰：三食旧徳，其卒也，斯谋斯猷皆我后之徳。从王事而无成，何以讼为？故从上吉。</li></ul><p>九四：不克讼，复即命，渝安贞，吉。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>不克讼，复即命，渝安贞，吉。九四刚而不中，故有讼象。以其居柔，故又为不克而复就正理，渝变其心，安处于正之象。占者知是则吉也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四以阳刚而居健体，不得中正，本为讼者也。承五履三而应初，五君也，义不克讼；三居下而柔，不与之讼；初正应而顺从，非与讼者也。四虽刚健欲讼，无与对敌，其讼无由而兴，故不克讼也。又居柔以应柔，亦为能止之义。既义不克讼，若能克其刚忿欲讼之心，复即就于命，革其心，平其气，变而为安贞，则吉矣。命谓正理，失正理为方命，故以即命为复也。方不顺也，书云：“方命圯族”。孟子曰：“方命虐民”。夫刚健而不中正，则躁动故不安，处非中正故不贞。不安贞，所以好讼也。若义不克讼而不讼，反就正理，变其不安贞为安贞，则吉矣。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>龚氏原曰：二与五讼，四与初讼。其与为敌者强弱不同，而皆曰不克者，盖二以下讼上，其不克者势也；四以上讼下，其不克者理也。二见势之不可，故归而逋窜；四知理之不可，故复而即命。二四皆刚居柔，故能如此。</li></ul><p>龚氏原曰：二与五讼，四与初讼。其与为敌者强弱不同，而皆曰不克者，盖二以下讼上，其不克者势也；四以上讼下，其不克者理也。二见势之不可，故归而逋窜；四知理之不可，故复而即命。二四皆刚居柔，故能如此。</p><ul><li>杨氏简曰：九刚四柔，有始讼终退之象。人惟不安于命，故以人力争讼。今不讼而即于命，变而安于贞吉之道也。</li></ul><p>杨氏简曰：九刚四柔，有始讼终退之象。人惟不安于命，故以人力争讼。今不讼而即于命，变而安于贞吉之道也。</p><p>象曰：复即命渝，安贞不失也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>能如是则为无失矣，所以吉也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>丘氏富国曰：二沮于势，四屈于理，此二之美所以止于无眚，而四之贞所以为不失也。</li></ul><p>九五：讼元吉。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>阳刚中正，以居尊位，聴讼而得其平者也。占者遇之，讼而有理，必获伸矣。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>以中正居尊位，治讼者也。治讼得其中正，所以元吉也。元吉，大吉而尽善也。吉大而不尽善者有矣。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏肃曰：以中正之徳，齐乖争之俗，元吉也。</p></li><li><p>王氏弼曰：处得尊位，为讼之主，用其中正以㫁枉直。中则不过，正则不邪，故讼元吉。</p></li><li><p>赵氏汝梅曰：大人在上，平诸侯万民之讼，至于见逊畔、逊路而息争，吉孰大焉。</p></li><li><p>俞氏琰曰：九五以刚明之徳居尊而又中正，彖辞所谓大人是也。讼之有理者见之，必获伸矣。元吉，乃吉之尽善者也。</p></li></ul><p>象曰：讼元吉，以中正也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>中则听不偏，正则断合理。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>中正之道，何施而不元吉。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏启新曰：中正则虚心尽下而听不偏，因事求情而断合理，此之谓大人也。</li></ul><p>上九：或锡之鞶带，终朝三禠之。</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>鞶带，命服之饰。禠，夺也。以刚居讼极，终讼而能胜之，故有锡命受服之象。然以讼得之，岂能安久？故又有终朝三禠之象。其占为终讼无理而或取胜，然其所得终必失之。圣人为戒之意深矣。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>九以阳居上，刚健之极，又处讼之终，极其讼者也。人之肆其刚强，穷极于讼，取祸䘮身，固其理也。设或使之善讼能胜，穷极不已，至于受服命之赏，是亦与人仇争所获，其能安保之乎？故终一朝而三见禠夺也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：处讼之极，以刚居上，讼而得胜者也。以讼受锡荣，何可保？故终朝之闲，禠带者三也。</p></li><li><p>胡氏炳文曰：上九以刚极处讼终，卦所谓终凶者也，故设此以戒之。</p></li></ul><p>象曰：以讼受服，亦不足敬也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>穷极讼事，设使受服命之宠，亦且不足敬而可贱恶，况又祸患随至乎。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>蔡氏清曰：亦不足敬，且据其以讼得服言也。况终必见褫乎？犹益上九曰“莫益之”，偏辞也。</li></ul><p>总论</p><p>邱氏富国曰：九五居尊，为聴讼之主，故讼元吉。馀五爻则皆讼者也。然天下惟刚者讼，柔者不讼。初与三柔也，故初不永所事而终吉，三食旧徳而终吉。二、四、上刚也。二与五对，揆势不敌而不讼；四与初对，顾理不可而不讼，亦以其居柔故。二无眚而四安贞也。独上九处卦之穷，下与三对，柔不能抗，故有锡鞶带之辞焉。然一日三禠，辱亦甚矣。讼之胜者，何足敬乎？</p>',120)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
